INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (0, 0.5, 100811, 5, "ふふ。ボクを呼んでくれて正解だよ。\nこの新年の晴れやかな日にこそ\nボクの輝く美貌が必要だからね！", 513043, 0, 11, 1, 513, 0);
